		} else {
			l.readChar()
			return l.NextToken()
		}
	}

	return tok
}

func isLetter(ch byte) bool {
	return unicode.IsLetter(rune(ch))
}

func isDigit(ch byte) bool {
	return unicode.IsDigit(rune(ch))
}

func lookupKeyword(ident string) ast.TokenType {
	switch ident {
	case "let":
		return ast.TokenLet
	case "fn":
		return ast.TokenFn
	case "if":
		return ast.TokenIf
	case "for":
		return ast.TokenFor
	case "in":
		return ast.TokenIn
	case "return":
		return ast.TokenReturn
	case "struct":
		return ast.TokenStruct
	case "true":
		return ast.TokenTrue
	case "false":
		return ast.TokenFalse
	case "else":
		return ast.TokenElse
	default:
		return ast.TokenIdent
	}
}

