func (p *Parser) parseExpression(prec int) (*ast.Node, error) {
	left, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}

	for prec < p.peekPrecedence() {
		p.nextToken()
		left, err = p.parseInfix(left)
		if err != nil {
			return nil, err
		}
	}

	return left, nil
}

func (p *Parser) parsePrimary() (*ast.Node, error) {
	switch p.curToken.Type {
	case ast.TokenInt:
		node := &ast.Node{
			Kind:  ast.NodeIntLit,
			Value: p.curToken.Value,
			Line:  p.curToken.Line,
			Col:   p.curToken.Col,
		}
		return node, nil

	case ast.TokenTrue:
		node := &ast.Node{
			Kind:  ast.NodeBoolLit,
			Value: "true",
			Line:  p.curToken.Line,
			Col:   p.curToken.Col,
		}
		return node, nil

	case ast.TokenFalse:
		node := &ast.Node{
			Kind:  ast.NodeBoolLit,
			Value: "false",
			Line:  p.curToken.Line,
			Col:   p.curToken.Col,
		}
		return node, nil

	case ast.TokenString:
		node := &ast.Node{
			Kind:  ast.NodeStringLit,
			Value: p.curToken.Value,
			Line:  p.curToken.Line,
			Col:   p.curToken.Col,
		}
		return node, nil

	case ast.TokenIdent:
		name := p.curToken.Value
		node := &ast.Node{
			Kind:  ast.NodeIdent,
			Value: name,
			Line:  p.curToken.Line,
			Col:   p.curToken.Col,
		}
		// Check if next token is '{' for struct initialization
		if p.peekToken.Type == ast.TokenLBrace {
			p.nextToken() // move to '{'
			return p.parseStructLit(name)
		}
		return node, nil

	case ast.TokenLParen:
		p.nextToken()
		expr, err := p.parseExpression(0)
		if err != nil {
			return nil, err
		}
		if p.curToken.Type != ast.TokenRParen {
			return nil, fmt.Errorf("expected ')'")
		}
		return expr, nil

	case ast.TokenLBracket:
		return p.parseArrayLit()

	default:
		return nil, fmt.Errorf("unexpected token: %v", p.curToken.Type)
	}
}

func (p *Parser) parseInfix(left *ast.Node) (*ast.Node, error) {
	// Handle field access: obj.field
	if p.curToken.Type == ast.TokenDot {
		p.nextToken() // consume '.'
		if p.curToken.Type != ast.TokenIdent {
			return nil, fmt.Errorf("expected field name after '.'")
		}
		return &ast.Node{
			Kind:     ast.NodeFieldAccess,
			Value:    p.curToken.Value,
			Line:     p.curToken.Line,
			Col:      p.curToken.Col,
			Children: []*ast.Node{left},
		}, nil
	}

	// Handle array indexing: arr[i]
	if p.curToken.Type == ast.TokenLBracket {
		return p.parseIndexExpr(left)
	}

	node := &ast.Node{
		Kind:     ast.NodeBinaryExpr,
		Line:     p.curToken.Line,
		Col:      p.curToken.Col,
		Value:    p.curToken.Value,
		Children: []*ast.Node{left},
	}

	prec := p.curPrecedence()
	p.nextToken()

	right, err := p.parseExpression(prec)
	if err != nil {
		return nil, err
	}
	node.Children = append(node.Children, right)

	// Handle function calls
	if left.Kind == ast.NodeIdent && p.curToken.Type == ast.TokenLParen {
		call := &ast.Node{
			Kind:  ast.NodeCallExpr,
			Value: left.Value,
		}
		p.nextToken() // consume '('
		for p.curToken.Type != ast.TokenRParen {
			arg, err := p.parseExpression(0)
			if err != nil {
				return nil, err
			}
			call.Children = append(call.Children, arg)
			if p.curToken.Type == ast.TokenComma {
				p.nextToken()
			}
		}
		p.nextToken() // consume ')'
		return call, nil
	}

	return node, nil
}
